import math

def calculate_sqrt(n):
    return math.sqrt(n)

test_suite:
def test_sqrt_of_perfect_square():
    result = exercise.calculate_sqrt(144)
    assert result == 12.0, f"Expected 12.0, got {result}"

def test_sqrt_of_zero():
    result = exercise.calculate_sqrt(0)
    assert result == 0.0, f"Expected 0.0, got {result}"

def test_sqrt_of_one():
    result = exercise.calculate_sqrt(1)
    assert result == 1.0, f"Expected 1.0, got {result}"

def test_sqrt_of_two():
    result = exercise.calculate_sqrt(2)
    assert abs(result - 1.41421356) < 0.0001, f"Expected ~1.4142, got {result}"

def test_sqrt_of_large_number():
    result = exercise.calculate_sqrt(1000000)
    assert result == 1000.0, f"Expected 1000.0, got {result}"

